// Offline population review only; does not run proofs or timing workloads.
use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fmt::Write,fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-real-replay175";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-real-g2-replay175";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn files(p:&Path)->Vec<std::path::PathBuf>{let mut v=vec![];for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){v.extend(files(&p))}else{v.push(p)}}v.sort();v}
fn main(){let root=Path::new(R);let dest=Path::new(D);let a=read(root.join("analysis.json"));let parent="/home/ubuntu/src/zopro-perf-work/loose-delta175/analysis.json";let p=read(parent);assert_eq!(p["component_gate"],true);
 let hot=&p["pairs"]["g2-borrowed-signed-200-logical32/on/off"];assert!(hot["low"].as_f64().unwrap()<1.&&hot["high"].as_f64().unwrap()>1.);let mut rows=BTreeMap::new();
 let mut section=String::from("## Population weighting and next test\n\nThe dominant observed prefix context is 200 pairs for every tested shape. The table accounts for all observed prefix contributions, not estimated CPU or wall-time costs.\n\n|Shape|Dominant caller / pairs|Point contributions|Share of prefix contributions|\n|---|---|---:|---:|\n");
 for(name,s)in a["shapes"].as_object().unwrap(){let top=s["histogram"].as_array().unwrap().iter().max_by_key(|h|h["points"].as_u64().unwrap()).unwrap();assert_eq!(top["pairs"],200);let share=top["points"].as_f64().unwrap()/s["prefix_points"].as_f64().unwrap();let mode=if top["borrowed"]==true{"signed borrowed"}else{"owned"};writeln!(section,"|{name}|{mode} / 200|{}|{:.3}%|",top["points"],share*100.).unwrap();rows.insert(name.clone(),json!({"dominant":top,"point_share":share}));}
 section.push_str("\nFor 1×2, signed borrowed 200-pair calls contribute **2,052,000 of 2,149,392 points (95.469%)**. Owned 512-pair calls add 81,920 points (3.811%); the earlier synthetic caller matrix did not time size 512. Its 18-context aggregate instead weights owned/borrowed 32/200/352 and one/16/32 workers equally. That aggregate is valid within its declared scope, but it is not the production population.\n\nThe earlier bounded-delta caller’s dominant signed-borrowed 200-pair/32-worker comparison has ON/OFF ratio **0.995330931**, bounds **[0.993716932, 1.002293063]**, and **10/15 wins**. Its interval spans parity even though the all-context aggregate passes. This did not establish an isolated gain in the main observed context. These population facts do not prove why the full SDK became slower, and neither old gate is reopened or relabeled. [Earlier caller observations](../2026-10-30-loose-delta175/README.md).\n\nA source/history review identifies a distinct next hypothesis: remove multiplication by one at the first G2 norm-prefix group and first reverse factor, and omit the dead final inverse update. The previous endpoint experiments changed G1’s stored-numerator scheme; they remain rejected. The current G2 prefix stores only chain/norm records, so this hypothesis changes a different recurrence. It is unimplemented and has no speed prediction. Before timing, emitted code must be checked for existing elimination; a candidate would need the real 200/512-pair fixtures, tails, the dominant caller, and complete-proof qualification. [Earlier G1 endpoint result](../2026-10-25-batch-endpoints-sdk/README.md).\n\nA fresh paper audit rechecked [SRE](https://arxiv.org/abs/2610.27452) against the existing [shared-window queue trial](../2026-10-25-shared-point-window-queue/README.md). Its reuse mechanism already has local studies; no paper speedup or implementation is transferred to this diagnostic.\n\n");
 let mut md=fs::read_to_string(dest.join("README.md")).unwrap();assert_eq!(md.matches("## Qualification and records").count(),1);md=md.replace("## Qualification and records",&format!("{section}## Qualification and records"));let old="No successful test, capture or proof verification was repeated.";assert_eq!(md.matches(old).count(),1);md=md.replace(old,"The first standalone auditor compilation also stopped before execution: Arkworks 0.5 exposes the ZERO constant through AdditiveGroup, whose import was missing. Adding that import fixed compilation; the successful native suites were reused. Original auditor/controller sources and compiler output are retained. No successful test, capture or proof verification was repeated.");md.push_str("\n[Offline population review](artifacts/population-review.json) and [review source](artifacts/postcapture-review.rs) add interpretation after capture; all original pinned helpers, raw captures and analysis remain unchanged.\n");fs::write(dest.join("README.md"),md).unwrap();
 fs::write(dest.join("artifacts/population-review.json"),serde_json::to_vec_pretty(&json!({"analysis_sha256":hash(root.join("analysis.json")),"parent_analysis_sha256":hash(parent),"dominant_contexts":rows,"parent_hot_context":hot,"point_share_is_CPU_or_wall_share":false,"cause_of_SDK_regression_isolated":false,"new_performance_gate":false,"old_caller_gate_changed":false,"old_SDK_gate_changed":false,"next_G2_endpoint_candidate_implemented":false,"original_pinned_helpers_changed":false})).unwrap()).unwrap();
 fs::copy(root.join("postcapture-review.rs"),dest.join("artifacts/postcapture-review.rs")).unwrap();for name in["finish.log","publish.log","audit-build.stderr","audit-build.stdout"]{fs::copy(root.join(name),dest.join("artifacts").join(name)).unwrap();}let sums=files(dest).iter().filter(|p|p.as_path()!=dest.join("SHA256SUMS")).map(|p|format!("{}  {}\n",hash(p),p.strip_prefix(dest).unwrap().display())).collect::<String>();fs::write(dest.join("SHA256SUMS"),sums).unwrap();println!("Reviewed all9 populations and prior hot-context interval; original helpers/data/gates unchanged");}
